<?phpnamespace App\Models;use Database\Factories\UserFactory;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;class User extends Authenticatable{    /** @use HasFactory<UserFactory> */    use HasFactory, Notifiable, HasUuids;    /**     * The attributes that are mass assignable.     *     * @var list<string>     */    protected $fillable = [        'first_name',        'last_name',        'email',        'private_email',        'password',        'pesel',    ];    /**     * The attributes that should be hidden for serialization.     *     * @var list<string>     */    protected $hidden = [        'password',        'pesel',        'remember_token',    ];    /**     * Get the attributes that should be cast.     *     * @return array<string, string>     */    protected function casts(): array    {        return [            'email_verified_at' => 'datetime',            'private_email_verified_at' => 'datetime',            'password' => 'hashed',        ];    }    /**     * @return string     */    public function getName(): string    {        $firstName = $this->firstName;        $lastName = $this->lastName;        return "$firstName $lastName";    }}